<script lang="ts">import type { Snippet } from 'svelte'; import type { HTMLButtonAttributes } from 'svelte/elements'; import { composeEventHandlers } from '../shared/events.js'; import { getComboboxChipContext, getComboboxContext } from './combobox-context.svelte.js'; export interface Props extends Omit<HTMLButtonAttributes, 'children'> { children?: Snippet; ref?: HTMLButtonElement | null; } let { children, ref = $bindable(null), onclick, ...rest }: Props = $props(); const box = getComboboxContext(); const chip = getComboboxChipContext();</script><button bind:this={ref} {...rest} type="button" aria-label={`Remove ${box.labelFor(chip.value)}`} disabled={box.disabled || box.readOnly} onclick={composeEventHandlers(onclick, (event) => box.select(chip.value, 'chip-remove', event))}>{@render children?.()}</button>
